settings.outformat = "png";
import graph;

// Set the size of the image
size(500, 350);

// Define a function that models the rapid rise and stabilization
// We use a scaled exponential decay model: y = L * (1 - e^(-kx))
real motionBlur(real x) {
    return 100 * (1 - exp(-1.5 * x));
}

// Generate the curve path
path curve = graph(motionBlur, 0, 5, operator ..);

// Define bright blue pen for the curve
pen brightBlue = rgb(0.1, 0.5, 1.0);

// Draw the curve
draw(curve, brightBlue + linewidth(2.5));

// Define the "Optimal" point at the knee of the curve
real xOpt = 0.9;
real yOpt = motionBlur(xOpt);

// Draw the dashed vertical line from the curve to the x-axis
draw((xOpt, 0)--(xOpt, yOpt), dashed + gray(0.3) + linewidth(1.2));

// Mark the intersection point
dot((xOpt, yOpt), brightBlue, linewidth(6));

// Add the "Optimal" label near the intersection
label("Optimal", (xOpt, yOpt), NW * 1.5, fontsize(12pt));

// Set up clean, minimalistic axes (without ticks to maintain a conceptual look)
xaxis(
    Label("Shutter Speed (seconds)", position=MidPoint, align=1.5S), 
    xmin=0, xmax=5.5, 
    Arrow(TeXHead)
);

yaxis(
    Label("Motion Blur", position=MidPoint, align=1.5W), 
    ymin=0, ymax=115, 
    Arrow(TeXHead)
);
```

