    return x^3 - 3 * x;
}

// Draw the smooth, continuous cubic curve in blue
// The range [-2.5, 2.5] is chosen to perfectly frame the rise, fall, and inflection behavior
draw(graph(f, -2.5, 2.5, n=400), blue + linewidth(1.5));

// Draw and label the x-axis and y-axis in black
// Arrowheads (TeXHead) indicate positive directions, and the labels are italicized using math mode
