settings.outformat = "png";
settings.render = 8;
import graph;

// Set the size of the graph
size(12cm, 8cm, IgnoreAspect);

// Define the data points for years and number of immigrants (in thousands)
real[] years = {2010, 2012, 2014, 2016, 2018, 2020};
real[] immigrants = {205, 225, 250, 265, 285, 300};

// Define the custom visual origin for the axes intersection
real origin_x = 2008;
real origin_y = 150;
real max_x = 2022;
real max_y = 330;

// Create the path for the line graph
path p = graph(years, immigrants);

// Draw the blue line connecting the data points
draw(p, blue + linewidth(1.5pt));

// Plot the red dots and annotate specific data values
for (int i = 0; i < years.length; ++i) {
    // Red dot
    dot((years[i], immigrants[i]), red + linewidth(5pt));

    // Data value label near the point
    label(string(immigrants[i]), (years[i], immigrants[i]), NW, fontsize(8pt) + gray(0.2));
}

// Configure and draw the X-axis (Années)
xaxis("Ann\'ees", 
      YEquals(origin_y), 
      origin_x, max_x,
      RightTicks(Label(fontsize(10pt)), new real[]{2010, 2012, 2014, 2016, 2018, 2020}),
      arrow=Arrow(6pt));

// Configure and draw the Y-axis (Nombre d'immigrants)
yaxis("Nombre d'immigrants (en milliers)", 
      XEquals(origin_x), 
      origin_y, max_y,
      LeftTicks(Label(fontsize(10pt)), new real[]{200, 250, 300}),
      arrow=Arrow(6pt));
```

