// Set the image format and dimensions
settings.outformat = "png";
settings.render = 8;
size(200, 150, IgnoreAspect);

import graph;

// Use a bold, readable font size
defaultpen(fontsize(9pt));

// Define the flow velocity function for a streamlined shape
// Simulates a smooth, gentle change in velocity across the object
real flow_streamlined(real x) {
    return 8.0 - 0.1 * (x - 5.0)^2;
}

// Define the flow velocity function for a blunt shape
// Simulates a sharp drop at the stagnation point, followed by a spike and wake fluctuations
real flow_blunt(real x) {
    return 5.0 - 4.0 * cos(x * 1.5) * exp(-0.3 * x);
}

// Generate the paths with a high number of sample points for a smooth, continuous appearance
path p_stream = graph(flow_streamlined, 0, 10, 200);
path p_blunt = graph(flow_blunt, 0, 10, 200);

// Plot the lines, assigning the respective colors and color-coded legend labels
draw(p_stream, red + linewidth(1.5), Label("\textbf{Streamlined shape}", red));
draw(p_blunt, blue + linewidth(1.5), Label("\textbf{Blunt shape}", blue));

// Draw the axes with bold text labels and evenly spaced bold ticks
xaxis("\textbf{Distance}", Bottom, xmin=0, xmax=10, Ticks(format="\textbf{%g}", Step=2, step=1));
yaxis("\textbf{Flow velocity}", Left, ymin=0, ymax=10, Ticks(format="\textbf{%g}", Step=2, step=1));

// Generate the legend and place it in a bordered box at the bottom right corner of the image
picture leg = legend();
add(bbox(leg, 3, black, Fill(white)), point(SE) + (-5, 5), NW);
```
